## [Copy link to heading](https://nextjs.org/blog/next-15#executing-code-after-a-response-with-unstable_after-experimental) Executing code after a response with `unstable_after` (Experimental)
```
const nextConfig = {
  experimental: {
    after: true,
  },
};

export default nextConfig;
```

```
import { unstable_after as after } from 'next/server';
import { log } from '@/app/utils';

export default function Layout({ children }) {
  // Secondary task
  after(() => {
    log();
  });

  // Primary task
  return <>{children}</>;
}
```

# after
## [Examples](https://nextjs.org/docs/15/app/api-reference/functions/after#examples)
### [With request APIs](https://nextjs.org/docs/15/app/api-reference/functions/after#with-request-apis)
```
import { after } from 'next/server'
import { cookies, headers } from 'next/headers'
import { logUserAction } from '@/app/utils'

export async function POST(request: Request) {
  // Perform mutation
  // ...

  // Log user activity for analytics
  after(async () => {
    const userAgent = (await headers().get('user-agent')) || 'unknown'
    const sessionCookie =
      (await cookies().get('session-id'))?.value || 'anonymous'

    logUserAction({ sessionCookie, userAgent })
  })

  return new Response(JSON.stringify({ status: 'success' }), {
    status: 200,
    headers: { 'Content-Type': 'application/json' },
  })
}
```

